import fs from 'node:fs';
const DEADLINE=1792564823, urls=['https://base-rpc.publicnode.com','https://mainnet.base.org','https://base-mainnet.public.blastapi.io'];
async function rpc(url,method,params){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jsonrpc:'2.0',id:1,method,params}),signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('HTTP '+r.status);const o=await r.json();if(o.error)throw Error('RPC refused '+o.error.code);return o.result;}
const heads=await Promise.all(urls.map(async url=>{try{if(Number(await rpc(url,'eth_chainId',[]))!==8453)throw Error('chain');return {url,number:Number(await rpc(url,'eth_blockNumber',[]))};}catch(e){return {url,error:e.message};}}));
console.log(JSON.stringify({heads}));const ok=heads.filter(x=>x.number);if(ok.length<2)throw Error('insufficient peers');const height=ok.map(x=>x.number).sort((a,b)=>b-a)[1]-2;
const rows=await Promise.all(ok.map(async p=>{try{const b=await rpc(p.url,'eth_getBlockByNumber',['0x'+height.toString(16),false]),ts=Number(b.timestamp),now=Date.now()/1000;if(Number(b.number)!==height||ts<=DEADLINE||ts>now+5||now-ts>120)throw Error('block not fresh/post-expiry');return {rpc:p.url,number:height,hash:b.hash,timestamp:ts};}catch(e){return {rpc:p.url,error:e.message};}}));
const win=rows.find(x=>x.hash&&rows.filter(y=>y.hash===x.hash&&y.timestamp===x.timestamp).length>=2);if(!win)throw Error('no matching post-expiry quorum '+JSON.stringify(rows));const out={at:new Date().toISOString(),signedReleaseDeadline:DEADLINE,agreedBlock:win,agreeingPeers:rows.filter(x=>x.hash===win.hash&&x.timestamp===win.timestamp).length,signaturesExpired:true,rows};fs.writeFileSync('outputs/decentralization-audit/linux-rollback-release-expiry.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify(out));
